def merge_intervals_strict(intervals):
    if not intervals:
        return []
    s = sorted(intervals, key=lambda x: x[0])
    out = [s[0][:]]
    for start, end in s[1:]:
        if start < out[-1][1]:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out

def atoi16(s):
    s = s.lstrip()
    if not s:
        return 0
    i, sign = 0, 1
    if s[0] in '+-':
        sign = -1 if s[0] == '-' else 1
        i = 1
    num = 0
    while i < len(s) and s[i].isdigit():
        num = num * 10 + int(s[i])
        i += 1
    num *= sign
    return max(-32768, min(32767, num))

def fizzbuzz_7_11(n):
    if n % 77 == 0:
        return 'FizzBuzz'
    if n % 7 == 0:
        return 'Fizz'
    if n % 11 == 0:
        return 'Buzz'
    return str(n)

def spiral_order_ccw(matrix):
    if not matrix or not matrix[0]:
        return []
    t = [list(row) for row in zip(*matrix)]
    out = []
    top, bottom = 0, len(t) - 1
    left, right = 0, len(t[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            out.append(t[top][c])
        top += 1
        for r in range(top, bottom + 1):
            out.append(t[r][right])
        right -= 1
        if top <= bottom:
            for c in range(right, left - 1, -1):
                out.append(t[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top - 1, -1):
                out.append(t[r][left])
            left += 1
    return out

def longest_unique_substring_text(s):
    seen = {}
    start = best_start = best_len = 0
    for i, c in enumerate(s):
        if c in seen and seen[c] >= start:
            start = seen[c] + 1
        seen[c] = i
        if i - start + 1 > best_len:
            best_len = i - start + 1
            best_start = start
    return s[best_start:best_start + best_len]

def roman_additive(s):
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    return sum(vals[c] for c in s)

def is_strict_parens(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
        else:
            return False
    return not stack
